  newId,
  "Follow up with Maya if she\u0027s not there by 6:30 PM.",
  now,
  1788269400.0,
  createdAt
);
console.log("Created new reminder:", newId);

// Verify
const matching = db.prepare("SELECT * FROM ts_reminders WHERE reminder_id = ?").get(newId);
console.log("New reminder:", JSON.stringify(matching, null, 2));
'
